const contexts=new WeakMap(),MAX_EVENTS=4096;
function prepareContext(context){let promise=contexts.get(context);if(!promise){if(!context?.audioWorklet?.addModule)throw Error('Sound-filter processing is unavailable in this browser.');promise=context.audioWorklet.addModule(new URL('./preview-bandpass-worklet.js',import.meta.url).href,{credentials:'same-origin'});contexts.set(context,promise);}return promise;}
function parameters(command){const args=command.args||[],low=Number(command.low??args[2]),high=Number(command.high??args[3]),id=command.workId??args[1];if(id==null||!Number.isFinite(low)||!Number.isFinite(high)||low<0||high<0||low>2147483647||high>2147483647)return null;return{id,low:Math.trunc(low),high:Math.trunc(high)};}
function captureSeconds(bus,frame){return bus._mixCapturing&&Number.isFinite(bus._forgeCaptureSeconds)?bus._forgeCaptureSeconds:Math.max(0,frame/(bus.fps||60));}
export class BandpassCommands{
 constructor(runner){this.runner=runner;this.bus=runner.audio;this.active=false;this.ready=false;this.failed=false;this.filters=new Map();this.registered=new Set();this.ended=new Set();this.nodes=new Map();this.allNodes=new Set();if(this.bus)this.bus._forgeBandpass=this;}
 async preload(commands=this.runner.commands){this.registered=new Set((commands||[]).filter(c=>['playSe','playSeLife','playSeVer2','playSeNotStoppable'].includes(c.type)&&c.workId!=null).map(c=>c.workId));this.active=Array.isArray(commands)&&commands.some(c=>c.type==='setBandpassFilter');if(!this.active)return;try{await prepareContext(this.bus._ensureCtx());this.ready=true;this.failed=false;}catch(error){this.failed=true;this.ready=false;this.runner.log?.('Preview limitation: this move uses a game sound filter that is not reproduced yet. Its original command is preserved for game export.');this.runner.log?.('Sound-filter setup: '+error.message);}}
 prepare(){this.clear();this.ended.clear();}
 execute(command){if(command.type!=='setBandpassFilter')return false;if(!this.active||!this.ready||this.failed)return false;const value=parameters(command);if(!value)return true;if(this.ended.has(value.id)||this.bus._forgeAudioWorkCancelled?.(value.id))return true;if(!this.registered.has(value.id)&&!(this.bus._forgeHasAudioWork?this.bus._forgeHasAudioWork(value.id):this.bus.voices?.has(value.id)))return true;if(value.low===0||value.high===0)return true;let events=this.filters.get(value.id);if(!events){events=[];this.filters.set(value.id,events);}if(events.length>=MAX_EVENTS){this.runner.log?.('Preview limitation: this move exceeds the supported sound-filter update limit.');return true;}const event={low:value.low,high:value.high,time:captureSeconds(this.bus,Number(command.frame)||0)};events.push(event);
  for(const mix of this.bus._mixEvents||[])if(mix.kind==='se'&&mix.forgeWorkId===value.id)mix.forgeBandpassFilters=events;
  if(!this.runner._forgeVisualSeeking)for(const node of this.nodes.get(value.id)||[])node.port.postMessage({type:'filter',time:this.bus.ctx.currentTime,low:value.low,high:value.high});return true;
 }
 connect(source,gain,key,context,timing={}){if(!this.active||!this.ready||typeof key==='string'&&key.startsWith('v:'))return false;const events=this.filters.get(key)||[],latest=events[events.length-1];const node=new AudioWorkletNode(context,'forge-native-bandpass-v1',{numberOfInputs:1,numberOfOutputs:1,channelCount:2,channelCountMode:'max',processorOptions:{events:latest?[{...latest,time:context.currentTime}]:[],endTime:this.endTime(source,timing)}});source.connect(node);node.connect(gain);let nodes=this.nodes.get(key);if(!nodes){nodes=new Set();this.nodes.set(key,nodes);}nodes.add(node);this.allNodes.add(node);node.port.onmessage=event=>{if(event.data?.type==='ended'){if(!this.bus.voices?.has(key)||this.bus.voices.get(key)?.src===source)this.ended.add(key);this.release(node);nodes.delete(node);if(!nodes.size)this.nodes.delete(key);}};source.addEventListener('ended',()=>{try{node.port.postMessage({type:'end',time:context.currentTime});}catch{}},{once:true});
  for(let i=(this.bus._mixEvents?.length||0)-1;i>=0;i--){const mix=this.bus._mixEvents[i];if(mix.kind==='se'&&mix.forgeWorkId===key){mix.forgeBandpassFilters=events;break;}}return true;
 }
 endTime(source,{when=0,offsetSec=0,rate=1,frame=0,endFrame=null,endSeconds=null}={}){let duration=source.loop?Infinity:Math.max(0,(source.buffer.duration-offsetSec)/rate);if(endFrame!=null&&endFrame>frame)duration=Math.min(duration,(endFrame-frame)/(this.bus.fps||60));if(Number.isFinite(endSeconds))duration=Math.min(duration,Math.max(0,endSeconds-when));return Number.isFinite(duration)?when+duration:null;}
 async prepareOffline(context,events){if(events.some(e=>e.forgeBandpassFilters?.length))await prepareContext(context);}
 connectOffline(source,gain,event,when){const filters=event.forgeBandpassFilters;if(!filters?.length)return false;const events=filters.map(value=>({...value,time:Math.max(when,value.time)}));const node=new AudioWorkletNode(source.context,'forge-native-bandpass-v1',{numberOfInputs:1,numberOfOutputs:1,channelCount:2,channelCountMode:'max',processorOptions:{events,endTime:this.endTime(source,{when,offsetSec:Math.max(0,Math.min(source.buffer.duration-.001,(Number(event.offsetMs)||0)/1000)),rate:Math.max(.35,Math.min(3,Number(event.playbackRate)||1)),frame:event.frame,endFrame:event.endFrame,endSeconds:event.forgeEndSeconds})}});source.connect(node);node.connect(gain);return true;}
 release(node){try{node.port.postMessage({type:'close'});node.disconnect();node.port.close();}catch{}this.allNodes.delete(node);}
 clear(){for(const node of this.allNodes)this.release(node);this.nodes.clear();this.filters=new Map();}
}
